-- 606: Original BrillaPrep Cambridge IGCSE Chemistry (0620) sprint 3 beta questions, part 13 of 13 (batch igcse-chemistry-sprint3-001).
-- Curriculum-aligned practice content; not official Cambridge International, WAEC or NSMQ examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_606_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_606_guard;
INSERT INTO _migration_606_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_049' AND NOT (q.topic_id IS 'topic_igcse_chem_reactions' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In the Haber process, N₂(g) + 3H₂(g) ⇌ 2NH₃(g), the forward reaction is exothermic. Which change increases the yield of ammonia at equilibrium?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Increasing the temperature","B. Adding more iron catalyst","C. Increasing the pressure","D. Decreasing the pressure"]' AND q.correct_answer IS 'C' AND q.explanation IS 'There are 4 moles of gas on the left and 2 on the right, so increasing the pressure shifts the equilibrium towards the fewer moles — the ammonia side. (The forward reaction is exothermic, so raising the temperature lowers the yield; a catalyst speeds up attainment of equilibrium but does not change the yield; decreasing the pressure favours the reactant side.) Therefore the correct answer is C: Increasing the pressure.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Deduce' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_049' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_606_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_050' AND NOT (q.topic_id IS 'topic_igcse_chem_reactions' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A student adds 2 g of marble chips (calcium carbonate) to 50 cm³ of dilute hydrochloric acid and measures the volume of carbon dioxide produced every 30 seconds.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂; (b) powder the marble chips and use more concentrated or warmer acid; (c) particles move faster and collide more often with enough energy to react.' AND q.explanation IS '(a) Calcium carbonate neutralises hydrochloric acid to give calcium chloride, water and carbon dioxide; the 2 in front of HCl balances the chlorine and hydrogen atoms. (b) Crushing the chips raises the surface area exposed to the acid, and a more concentrated or warmer acid gives more frequent, more energetic collisions. (c) At higher temperature the particles move faster, so collisions are both more frequent and more often energetic enough to break bonds and react.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '4' AND q.time_limit IS '300' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_050' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_049', 'topic_igcse_chem_reactions', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'In the Haber process, N₂(g) + 3H₂(g) ⇌ 2NH₃(g), the forward reaction is exothermic. Which change increases the yield of ammonia at equilibrium?', 'multiple_choice', NULL, '["A. Increasing the temperature","B. Adding more iron catalyst","C. Increasing the pressure","D. Decreasing the pressure"]', 'C', 'There are 4 moles of gas on the left and 2 on the right, so increasing the pressure shifts the equilibrium towards the fewer moles — the ammonia side. (The forward reaction is exothermic, so raising the temperature lowers the yield; a catalyst speeds up attainment of equilibrium but does not change the yield; decreasing the pressure favours the reactant side.) Therefore the correct answer is C: Increasing the pressure.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Deduce', 'AO3', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_050', 'topic_igcse_chem_reactions', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'A student adds 2 g of marble chips (calcium carbonate) to 50 cm³ of dilute hydrochloric acid and measures the volume of carbon dioxide produced every 30 seconds.', 'structured', NULL, NULL, '(a) CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂; (b) powder the marble chips and use more concentrated or warmer acid; (c) particles move faster and collide more often with enough energy to react.', '(a) Calcium carbonate neutralises hydrochloric acid to give calcium chloride, water and carbon dioxide; the 2 in front of HCl balances the chlorine and hydrogen atoms. (b) Crushing the chips raises the surface area exposed to the acid, and a more concentrated or warmer acid gives more frequent, more energetic collisions. (c) At higher temperature the particles move faster, so collisions are both more frequent and more often energetic enough to break bonds and react.', 'medium', '4', '4', '300', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'igcse-chemistry-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/', 0, 1 FROM questions WHERE id IN ('q_igcse_chem_s3_049', 'q_igcse_chem_s3_050');
